    movement = apps.get_model("inventory", "StockMovement")
    step = apps.get_model("inventory", "StockTransferStep")
    for out_id, in_id in step.objects.order_by("pk").values_list("out_movement_id", "in_movement_id"):
        movement.objects.filter(pk=in_id, moved_from__isnull=True).update(moved_from_id=out_id)
    taken = set(movement.objects.filter(moved_from__isnull=False).values_list("moved_from_id", flat=True))
    for arrival in movement.objects.filter(movement_type="transfer_in", moved_from__isnull=True).order_by("pk"):
        departure = (movement.objects.filter(
            pk__lt=arrival.pk, movement_type="transfer_out", item_id=arrival.item_id, lot_id=arrival.lot_id,
            reference=arrival.reference, occurred_at=arrival.occurred_at, quantity=-arrival.quantity,
            unit_cost=arrival.unit_cost,
        ).exclude(warehouse_id=arrival.warehouse_id).exclude(pk__in=taken).order_by("-pk").first())
        if departure is not None:
            movement.objects.filter(pk=arrival.pk).update(moved_from_id=departure.pk)
            taken.add(departure.pk)


